// Auto-generated OBJ tile numbers: the OBJ tile number of a sprite sheet tile at
// (col, row) is row*16 + col.  The 32x32 pizzas (LARGE, GIANT) are four 16x16 sprites;
// the define is the top-left one, the others are +2 (TR), +32 (BL) and +34 (BR).
#define SPR_HEAD 0
#define SPR_PIZZA_BIG 1
#define SPR_PIZZA_SMALL 3
#define SPR_BODY 4
#define SPR_PIZZA_MEDIUM 5
#define SPR_PIZZA_LARGE 7
#define SPR_PIZZA_GIANT 11
